238	\begin{lemma}[Consistency for measurements]\label{prop:simeq-for-measurements}
239		\lean{MIPStarRE.LDT.Preliminaries.simeqForMeasurements}
240		\leanok
241		\uses{def:simeq}
242		If $A=\{A_a^x\}$ and $B=\{B_a^x\}$ are measurements, then
243		\[
244			A_a^x \ot I \simeq_\delta I \ot B_a^x
245			\qquad\text{if and only if}\qquad
246			\E_x \sum_a \bra{\psi} A_a^x \ot B_a^x \ket{\psi} \ge 1-\delta.
247		\]
248	\end{lemma}
249	\begin{proof}
250		\leanok
251		Expand the off-diagonal sum by writing $\sum_{a \ne b} A_a^x \ot B_b^x = \sum_b (I-A_b^x) \ot B_b^x$.
252	\end{proof}
