254	\begin{definition}[State-dependent distance]\label{def:approx_delta}
255		\lean{MIPStarRE.LDT.SDDRel}
256		\leanok
257		Let $\ket{\psi} \in \mathcal H$, let $A=\{A_a^x\}$ and $B=\{B_a^x\}$ be families of operators on $\mathcal H$, and let $\mathcal D$ be a distribution on the question set. We write
258		\[
259			A_a^x \approx_\delta B_a^x
260		\]
261		when
262		\[
263			\E_{x \sim \mathcal D} \sum_a \lVert (A_a^x-B_a^x)\ket{\psi} \rVert^2 \le \delta.
264		\]
265	\end{definition}
266	
267	In particular, if $A^x_a \ot I \simeq_{\eps} I \ot C^x_a$, the question is what hypothesis on $A$ and $B$ allows one to conclude that
268	\begin{equation}\label{eq:can-we-use-approx-delta-to-derive-this}
269		B^x_a \ot I \simeq_{\eps} I \ot C^x_a.
270	\end{equation}
