272	\begin{lemma}[Transferring consistency through state-dependent distance]\label{prop:triangle-sub}
273		\lean{MIPStarRE.LDT.Preliminaries.triangleSub_heterogeneous}
274		\leanok
275		\uses{def:simeq, def:approx_delta, prop:simeq-for-measurements}
276		Let $A=\{A_a^x\}$ and $B=\{B_a^x\}$ be measurements and let $C=\{C_a^x\}$ be a submeasurement. If $A_a^x \ot I \simeq_\delta I \ot C_a^x$ and $A_a^x \ot I \approx_\eps B_a^x \ot I$, then
277		\[
278			B_a^x \ot I \simeq_{\delta+\sqrt\eps} I \ot C_a^x.
279		\]
280	\end{lemma}
281	\begin{proof}
282		\leanok
283		Rewrite the inconsistency with $C$ as total mass minus diagonal overlap. The total mass is unchanged because $A$ and $B$ are measurements, and the diagonal overlap changes by at most $\sqrt\eps$ by Cauchy--Schwarz.
284	\end{proof}
