286	\begin{lemma}[Consistency implies state-dependent distance for measurements]\label{prop:simeq-to-approx}
287		\lean{MIPStarRE.LDT.Preliminaries.simeqToApprox_heterogeneous, MIPStarRE.LDT.Preliminaries.approxToSimeq_heterogeneous}
288		\leanok
289		\uses{def:simeq, def:approx_delta, prop:simeq-for-measurements}
290		If $A$ and $B$ are measurements and $A_a^x \ot I \simeq_\delta I \ot B_a^x$, then
291		\[
292			A_a^x \ot I \approx_{2\delta} I \ot B_a^x.
293		\]
294		If both measurements are projective, the converse also holds: if $A_a^x \ot I \approx_{2\delta} I \ot B_a^x$ then $A_a^x \ot I \simeq_\delta I \ot B_a^x$.
295	\end{lemma}
296	\begin{proof}
297		\leanok
298		Expand the squared norm of $(A_a^x \ot I - I \ot B_a^x)\ket{\psi}$ and use the diagonal-overlap formula from Lemma~\ref{prop:simeq-for-measurements}; projectivity turns the diagonal inequality into an equality, giving the converse.
299	\end{proof}
